// Asteroid Escape – minimal canvas game
// Targets <canvas id="game"></canvas> assumed present in the page.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const DPR = window.devicePixelRatio || 1;
  const resize = () => {
    canvas.width = canvas.clientWidth * DPR;
    canvas.height = canvas.clientHeight * DPR;
    ctx.scale(DPR, DPR);
  };
  resize();
  window.addEventListener('resize', resize);

  // ---- Game state ----
  const ship = { x: canvas.width / 2, y: canvas.height - 60, w: 30, h: 40, speed: 4 };
  const keys = {};
  const asteroids = [];
  let lastSpawn = 0;
  let score = 0;
  let gameOver = false;

  // ---- Input ----
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));
  canvas.addEventListener('mousemove', e => {
    const rect = canvas.getBoundingClientRect();
    ship.x = (e.clientX - rect.left) * DPR;
  });

  const spawnAsteroid = () => {
    const size = 20 + Math.random() * 30;
    const x = Math.random() * (canvas.width - size);
    const y = -size;
    const speed = 2 + Math.random() * 2;
    asteroids.push({ x, y, size, speed });
  };

  const update = dt => {
    if (gameOver) return;
    // ship movement (arrow keys fallback)
    if (keys.ArrowLeft) ship.x -= ship.speed;
    if (keys.ArrowRight) ship.x += ship.speed;
    ship.x = Math.max(0, Math.min(canvas.width - ship.w, ship.x));

    // spawn
    if (performance.now() - lastSpawn > 800) {
      spawnAsteroid();
      lastSpawn = performance.now();
    }

    // update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // collision
      if (
        a.x < ship.x + ship.w && a.x + a.size > ship.x &&
        a.y < ship.y + ship.h && a.y + a.size > ship.y
      ) {
        gameOver = true;
      }
      // remove off‑screen
      if (a.y > canvas.height) asteroids.splice(i, 1);
    }
    score += dt;
  };

  const draw = () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // starfield background (simple)
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // ship (triangle)
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(ship.x, ship.y + ship.h);
    ctx.lineTo(ship.x + ship.w / 2, ship.y);
    ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
    ctx.closePath();
    ctx.fill();
    // asteroids
    ctx.fillStyle = '#888';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x + a.size / 2, a.y + a.size / 2, a.size / 2, 0, Math.PI * 2);
      ctx.fill();
    });
    // score / game over text
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${Math.floor(score / 1000)}`, 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#f00';
      ctx.font = '32px sans-serif';
      ctx.fillText('Game Over', canvas.width / 2 - 80, canvas.height / 2);
    }
  };

  let last = performance.now();
  const loop = now => {
    const dt = now - last;
    last = now;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
})();
